import Cocoa

// Create keyboard event for Return key (key code 36)
let source = CGEventSource(stateID: .hidSystemState)

if let event = CGEvent(keyboardEventSource: source, virtualKey: 36, keyDown: true) {
    event.post(tap: .cghidEventTap)
}

usleep(50000)

if let event = CGEvent(keyboardEventSource: source, virtualKey: 36, keyDown: false) {
    event.post(tap: .cghidEventTap)
}

print("Return key pressed")
sleep(1)
